/*
 * A225405  10-adic integer x such that x^3 = 7.
 * https://oeis.org/A225405
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = digit n of the 10‑adic integer x such that x^3 = 7
 *            Recurrence (single‑digit implementation): a(0) = 3. For i ≥ 1
 *            let t be the i‑th digit of (x mod 10^(i+1))^3. a(i) = (10 -
 *            (3·t) mod 10) mod 10. The sequence is generated by maintaining b
 *            – current value of x modulo 10^m (digits 0…m‑1) s –...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   add_int_at_offset, add_mult_at_offset
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>
#include "../utils/add_int_at_offset.h"
#include "../utils/add_mult_at_offset.h"

#define CAP 40005   /* maximum number of decimal digits needed (n≈10000) */

/* decimal‑digit arrays are stored least‑significant digit first */

static uint8_t *b = NULL;      /* current value b   (length len_b)        */
static uint8_t *s = NULL;      /* b^2                (length len_s)      */
static uint8_t *c = NULL;      /* b^3                (length len_c)      */

static size_t len_b = 0;       /* number of digits of b            */
static size_t len_s = 0;       /* number of digits of s            */
static size_t len_c = 0;       /* number of digits of c            */

static size_t already_computed = 0;   /* highest n for which a(n) known */

/* initialise the static buffers on first call */
static void init_buffers(void)
{
    if (b) return;          /* already initialised */

    b = (uint8_t *)malloc(CAP);
    s = (uint8_t *)malloc(CAP);
    c = (uint8_t *)malloc(CAP * 3 / 2 + 10);   /* c needs more space      */

    /* a(0) = 3 */
    b[0] = 3;  len_b = 1;

    /* s = b^2 = 9 */
    s[0] = 9;  len_s = 1;

    /* c = b^3 = 27 → [7,2] */
    c[0] = 7;  c[1] = 2;  len_c = 2;

    already_computed = 0;   /* because a(0) is already available */
}

/* the required function */
seq_t a(idx_t n)
{
    init_buffers();

    /* generate digits up to index n (inclusive) */
    while (already_computed <= n) {
        size_t i = len_b;              /* i is the next digit position   */
        uint8_t t = (i < len_c) ? c[i] : 0;
        uint8_t d = (10 - (3 * t) % 10) % 10;

        b[i] = d;          /* append new digit           */
        ++len_b;

        /* UPDATE C first – use old values of s and b */
        add_mult_at_offset(c, &len_c, s, len_s, 3 * d, i);              /* 3*d*s*10^i      */
        add_mult_at_offset(c, &len_c, b, i, 3 * d * d, 2 * i);          /* 3*d^2*b*10^(2i) */
        add_int_at_offset (c, &len_c, d * d * d, 3 * i);                /* d^3*10^(3i)     */

        /* UPDATE S */
        add_mult_at_offset(s, &len_s, b, i, 2 * d, i);                 /* 2*d*b*10^i      */
        add_int_at_offset (s, &len_s, d * d, 2 * i);                   /* d^2*10^(2i)     */

        ++already_computed;
    }

    return (seq_t)b[(size_t)n];
}
